(() => {
  'use strict';
  const KEY='nexusCollectionV1';
  const catalog=[
    {id:'lantern',name:'Lantern Fragment',rarity:'Common',art:'memory-art/notebook.jpg',lore:'A spark for those who keep searching.'},
    {id:'compass',name:'Wandering Compass',rarity:'Common',art:'memory-art/compass.jpg',lore:'Its needle points toward unanswered questions.'},
    {id:'scroll',name:'Mission Scroll',rarity:'Uncommon',art:'memory-art/mission-scroll.jpg',lore:'An old promise waits to be kept.'},
    {id:'key',name:'Hidden Gate Key',rarity:'Rare',art:'memory-art/nexus-key.jpg',lore:'Only the curious can find the right door.'},
    {id:'portal',name:'Portal Echo',rarity:'Epic',art:'memory-art/portal.jpg',lore:'A doorway that remembers every visitor.'},
    {id:'wolf',name:'First Keeper’s Sigil',rarity:'Legendary',art:'memory-art/wolf.jpg',lore:'The gate remembers its guardian.'},
    {id:'star',name:'Nexus Star',rarity:'Mythic',art:'memory-art/card-back.jpg',lore:'A secret no Keeper has fully explained.'}
  ];
  const themes=['Courage','Curiosity','Kindness','Focus','Discovery','Teamwork'];
  const keeperLines=['The Nexus remembers your effort.','Keep your eyes open. Not every clue announces itself.','You have come farther than you know.'];
  const weekKey=(date=new Date())=>{const d=new Date(Date.UTC(date.getFullYear(),date.getMonth(),date.getDate()));d.setUTCDate(d.getUTCDate()+4-(d.getUTCDay()||7));const y=d.getUTCFullYear(),start=new Date(Date.UTC(y,0,1));return `${y}-W${String(Math.ceil((((d-start)/86400000)+1)/7)).padStart(2,'0')}`};
  const today=()=>new Date().toLocaleDateString('en-CA');
  const initial={cards:[],showcase:[],wins:[],streak:0,lastVisit:'',totalEarned:0,perks:{},weekStats:{},keeperSeen:[],revealQueue:[]};
  let state;try{state={...initial,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{state={...initial}};
  const persist=()=>localStorage.setItem(KEY,JSON.stringify(state));
  const app=document.querySelector('.app');if(!app)return;
  const style=document.createElement('style');style.textContent=`
  #nexusUpdateDialog{width:min(720px,calc(100% - 24px));max-height:92dvh;overflow:auto;border-color:#bd8aff}
  #nexusUpdateDialog .modal{padding:18px}.nx-tabs{display:flex;gap:6px;overflow-x:auto;margin:12px 0}.nx-tabs button{white-space:nowrap;padding:9px 12px;border:1px solid #796ab2;border-radius:12px;background:#17183a;color:#fff}
  .nx-tabs button[aria-selected=true]{background:#663bc0}.nx-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(128px,1fr));gap:9px}.nx-card{position:relative;border:2px solid #aaa9c6;border-radius:13px;overflow:hidden;background:#0c1028;color:white;text-align:left;padding:0;min-height:212px}
  .nx-card[data-rarity=Uncommon]{border-color:#66d9aa}.nx-card[data-rarity=Rare]{border-color:#5ab5ff}.nx-card[data-rarity=Epic]{border-color:#bc75ff}.nx-card[data-rarity=Legendary],.nx-card[data-rarity=Mythic]{border-color:#ffd46d;box-shadow:0 0 12px #e7a64088}
  .nx-card img{width:100%;aspect-ratio:1;object-fit:cover;display:block}.nx-card strong,.nx-card small,.nx-card em{display:block;padding:0 8px}.nx-card strong{font-size:14px;margin-top:7px}.nx-card small{color:#efdc9c;font-size:12px;margin:4px 0}.nx-card em{font-style:normal;font-size:12px;color:#b9c5df;margin-bottom:8px}.nx-card b{position:absolute;top:4px;right:5px;border-radius:9px;padding:2px 6px;background:#16172bdd}
  .nx-panel{padding:12px;border:1px solid #565486;border-radius:12px;margin:10px 0;background:#101737}.nx-panel p{margin:6px 0}.nx-panel button,.nx-action{min-height:44px;margin:6px 6px 4px 0;padding:9px 13px;border-radius:11px;border:1px solid #b48cff;background:#342569;color:#fff;font-weight:700}.nx-panel button:disabled{opacity:.5}.nx-meter{height:10px;border-radius:9px;background:#2b3152;overflow:hidden}.nx-meter i{display:block;height:100%;background:linear-gradient(90deg,#8b5ff2,#ffd56c)}
  #nexusReveal{position:fixed;inset:0;z-index:150;background:#030612ec;display:none;place-items:center;padding:24px;text-align:center}#nexusReveal.open{display:grid}.nx-reveal-card{width:min(290px,80vw);animation:nxRise .75s cubic-bezier(.2,.8,.2,1) both}.nx-reveal-card .nx-card{width:100%;min-height:400px}.nx-reveal-card .nx-card img{aspect-ratio:1.1}.nx-reveal-card .nx-card strong{font-size:21px}.nx-reveal-card .nx-card small,.nx-reveal-card .nx-card em{font-size:15px}.nx-reveal-glow{filter:drop-shadow(0 0 28px #ad65ff);animation:nxGlow 1.4s ease-in-out infinite alternate}
  @keyframes nxRise{from{transform:translateY(80px) rotateY(90deg) scale(.65);opacity:0}to{transform:translateY(0) rotateY(0) scale(1);opacity:1}}@keyframes nxGlow{to{filter:drop-shadow(0 0 38px #ffd465)}}@media(prefers-reduced-motion:reduce){.nx-reveal-card,.nx-reveal-glow{animation:none}}
  `;document.head.append(style);
  const launch=document.createElement('button');launch.type='button';launch.className='choice';launch.textContent='✦ NEXUS VAULT · WEEKLY QUESTS';launch.style.cssText='display:block;width:calc(100% - 34px);margin:12px 17px;border-color:#b68aff';app.querySelector('main')?.prepend(launch);
  const dlg=document.createElement('dialog');dlg.id='nexusUpdateDialog';dlg.innerHTML='<div class="modal"><small>YOUR NEXUS</small><h2 id="nxTitle">NEXUS VAULT</h2><div class="nx-tabs" role="tablist"></div><div id="nxBody"></div><button class="close" type="button" style="width:100%;margin-top:12px">Back to HQ</button></div>';document.body.append(dlg);
  const reveal=document.createElement('div');reveal.id='nexusReveal';reveal.setAttribute('role','dialog');reveal.setAttribute('aria-modal','true');document.body.append(reveal);
  const tabs=['Vault','Hero','This week','Keeper'];let active='Vault';
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function cardHTML(c,n=1,selected=false){return `<button type="button" class="nx-card" data-card="${c.id}" data-rarity="${c.rarity}" aria-label="${esc(c.name)}, ${c.rarity}${selected?', in Showcase':''}"><img src="${c.art}" alt=""><b>${n>1?'×'+n:selected?'★':''}</b><strong>${esc(c.name)}</strong><small>${c.rarity}</small><em>${esc(c.lore)}</em></button>`}
  function showReveal(c){reveal.innerHTML=`<div class="nx-reveal-glow"><p>✦ FRAGMENT DISCOVERED ✦</p><div class="nx-reveal-card">${cardHTML(c)}</div><button class="nx-action" id="nxRevealContinue">CONTINUE</button></div>`;reveal.classList.add('open');reveal.querySelector('button.nx-card').disabled=true;reveal.querySelector('#nxRevealContinue').focus()}
  reveal.onclick=e=>{if(e.target.id==='nxRevealContinue'){reveal.classList.remove('open');reveal.replaceChildren();const next=state.revealQueue.shift();persist();if(next)showReveal(catalog.find(c=>c.id===next))}};
  function award(id){const c=catalog.find(x=>x.id===id);if(!c)return;state.cards.push(id);state.revealQueue.push(id);persist();if(!reveal.classList.contains('open')){state.revealQueue.shift();persist();showReveal(c)}if(dlg.open)draw()}
  function keeper(msg){const box=document.createElement('div');box.className='nx-panel';box.innerHTML='<img src="episode-1/Episode-1-Panel-07-The-First-Keeper-App.jpg" alt="The First Keeper" style="width:100%;max-height:210px;object-fit:cover;border-radius:9px"><strong>THE FIRST KEEPER</strong><p></p><button type="button">Continue</button>';box.querySelector('p').textContent=msg;const prior=document.querySelector('#nxKeeperMoment');prior?.remove();box.id='nxKeeperMoment';document.body.append(box);box.style.cssText='position:fixed;z-index:145;left:16px;right:16px;top:22%;max-width:430px;margin:auto;box-shadow:0 0 0 100vmax #000b,0 0 32px #a56cff';box.querySelector('button').onclick=()=>box.remove()}
  function visit(){const d=today();if(state.lastVisit===d)return;const yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);state.streak=state.lastVisit===yesterday.toLocaleDateString('en-CA')?state.streak+1:1;state.lastVisit=d;persist();if([3,7,10].includes(state.streak)&&!state.keeperSeen.includes('s'+state.streak)){state.keeperSeen.push('s'+state.streak);persist();setTimeout(()=>keeper(`${state.streak} days at the Nexus. Your resolve is growing.`),700)}}
  function draw(){const body=dlg.querySelector('#nxBody');dlg.querySelector('#nxTitle').textContent=active==='Vault'?'NEXUS VAULT':active==='Hero'?'HERO GROWTH':active==='This week'?'THIS WEEK':'THE FIRST KEEPER';dlg.querySelector('.nx-tabs').innerHTML=tabs.map(t=>`<button type="button" data-tab="${t}" role="tab" aria-selected="${active===t}">${t}</button>`).join('');const counts=Object.fromEntries(catalog.map(c=>[c.id,state.cards.filter(id=>id===c.id).length]));
    if(active==='Vault'){body.innerHTML=`<p>Discover fragments as you play. Tap a card to add or remove it from your six-card Showcase.</p><div class="nx-panel"><strong>SHOWCASE · ${state.showcase.length}/6</strong><p>${state.showcase.length?state.showcase.map(id=>esc(catalog.find(c=>c.id===id)?.name||'')).join(' · '):'Choose cards below to display here.'}</p></div><div class="nx-grid">${catalog.filter(c=>counts[c.id]).map(c=>cardHTML(c,counts[c.id],state.showcase.includes(c.id))).join('')||'<p>Your first fragment is waiting. Complete a game or weekly quest.</p>'}</div><div class="nx-panel">🔒 Undiscovered fragments: ${catalog.length-Object.keys(counts).filter(k=>counts[k]).length}. Their clues stay hidden until found.</div><p>Trades will open when squad accounts can verify both players and card ownership.</p>`}
    else if(active==='Hero'){const earned=Number(state.totalEarned||0),level=Math.floor(earned/100)+1;body.innerHTML=`<div class="nx-panel"><strong>HERO LEVEL ${level}</strong><p>${earned%100}/100 XP to next level · XP does not decrease when points are spent.</p><div class="nx-meter"><i style="width:${earned%100}%"></i></div></div><div class="nx-panel"><strong>POINTS · ${Number(window.nexusPoints||0)}</strong><p>Choose a small perk. Character Lab has your outfits and accessories.</p><button data-perk="hint">${state.perks.hint||0} hints · Buy 1 for 40 points</button><button data-perk="retry">${state.perks.retry||0} second chances · Buy 1 for 60 points</button></div><div class="nx-panel">NEXT TARGET · ${100-earned%100} XP until Level ${level+1}<p>Earn XP from first game clears, fragment discoveries, and weekly challenges.</p></div>`}
    else if(active==='This week'){const w=weekKey(),stats=state.weekStats[w]||{},idx=Number(w.slice(-2))%themes.length,theme=themes[idx],done=!!stats.anomaly;body.innerHTML=`<div class="nx-panel"><strong>THEME OF THE WEEK · ${theme.toUpperCase()}</strong><p>A fresh focus every week.</p></div><div class="nx-panel"><strong>NEXUS ANOMALY · ${done?'SOLVED':'OPEN'}</strong><p>About five minutes: solve a pattern, then discover a fragment. One reward per week.</p><button data-action="anomaly" ${done?'disabled':''}>${done?'Completed':'BEGIN ANOMALY'}</button></div><div class="nx-panel"><strong>WEEKLY BONUS</strong><p>Complete three different arcade games this week. ${Math.min(stats.games?.length||0,3)}/3</p><button data-action="bonus" ${stats.bonus||((stats.games?.length||0)<3)?'disabled':''}>${stats.bonus?'Claimed':'CLAIM +40 POINTS'}</button></div><div class="nx-panel"><strong>SQUAD CHALLENGE</strong><p>Score three game clears this week to prepare for squad play. ${Math.min(stats.games?.length||0,3)}/3</p><p>Shared squad scores unlock with connected squad accounts.</p></div><div class="nx-panel"><strong>WEEKLY RECAP</strong><p>${stats.games?.length||0} game clears · ${stats.anomaly?'Anomaly solved':'Anomaly waiting'} · ${state.streak} day login streak</p><p>${keeperLines[idx%keeperLines.length]}</p><small>Next week brings a new theme and anomaly.</small></div>`}
    else{body.innerHTML=`<div class="nx-panel"><strong>THE KEEPER GUARDS THE NEXUS</strong><p>${keeperLines[(state.streak||0)%keeperLines.length]}</p><p>Login streak: ${state.streak} day${state.streak===1?'':'s'}. Milestones at 3, 7, and 10 days.</p></div><div class="nx-panel"><strong>KEEPER SECRETS</strong><p>Find fragments and solve the weekly anomaly to reveal pieces of the story. Some discoveries are intentionally hidden.</p></div>`}
  }
  launch.onclick=()=>{active='Vault';draw();dlg.showModal()};dlg.querySelector('.close').onclick=()=>dlg.close();dlg.onclick=e=>{const tab=e.target.closest('[data-tab]');if(tab){active=tab.dataset.tab;draw();return}const card=e.target.closest('[data-card]');if(card){const id=card.dataset.card,idx=state.showcase.indexOf(id);if(idx>=0)state.showcase.splice(idx,1);else if(state.showcase.length<6)state.showcase.push(id);else{note('Your Showcase is full');return}persist();draw();return}const perk=e.target.closest('[data-perk]');if(perk){const type=perk.dataset.perk,cost=type==='hint'?40:60;if(Number(window.nexusPoints)<cost){note('Earn more points first');return}window.nexusPoints=Number(window.nexusPoints)-cost;state.perks[type]=(state.perks[type]||0)+1;persist();window.save();window.render();draw();return}const action=e.target.closest('[data-action]');if(action?.dataset.action==='anomaly')startAnomaly();if(action?.dataset.action==='bonus'){const w=weekKey(),s=state.weekStats[w];if(!s||s.bonus||(s.games?.length||0)<3)return;s.bonus=true;window.nexusPoints=Number(window.nexusPoints)+40;state.totalEarned+=40;persist();window.save();window.render();draw();award('scroll')}};
  const anomaly=document.createElement('dialog');anomaly.id='nxAnomaly';anomaly.innerHTML='<div class="modal"><small>WEEKLY ANOMALY</small><h2>THE SHIFTING SIGNAL</h2><p>Watch the sequence. Which symbol comes next?</p><p style="font-size:32px;text-align:center">✦ ◆ ✦ ◆ ✦ ?</p><div class="choices"><button class="choice" data-answer="star">✦ STAR</button><button class="choice" data-answer="diamond">◆ DIAMOND</button><button class="choice" data-answer="circle">● CIRCLE</button></div><p id="nxFeedback" aria-live="polite"></p><button class="close" type="button">Back</button></div>';document.body.append(anomaly);anomaly.querySelector('.close').onclick=()=>anomaly.close();
  function startAnomaly(){dlg.close();anomaly.querySelector('#nxFeedback').textContent='';anomaly.showModal()}
  anomaly.onclick=e=>{const b=e.target.closest('[data-answer]');if(!b)return;if(b.dataset.answer!=='diamond'){const hint=state.perks.hint||0;if(hint){state.perks.hint--;persist();anomaly.querySelector('#nxFeedback').textContent='Hint used: the two symbols alternate. Try again.'}else anomaly.querySelector('#nxFeedback').textContent='Look at how the symbols alternate. Try again.';return}const w=weekKey(),s=state.weekStats[w]||{};if(s.anomaly){anomaly.close();return}s.anomaly=true;state.weekStats[w]=s;state.totalEarned+=50;window.nexusPoints=Number(window.nexusPoints)+50;persist();window.save();window.render();anomaly.close();award('portal');setTimeout(()=>keeper('You noticed the pattern. The gate has noticed you.'),600)};
  const awards=['lantern','compass','scroll','key','portal'];window.addEventListener('nexus:clear',e=>{const id=e.detail?.id||'',w=weekKey(),s=state.weekStats[w]||{games:[]};s.games||=[];if(!s.games.includes(id))s.games.push(id);state.weekStats[w]=s;state.totalEarned+=10;persist();const count=state.wins.length;if(!state.wins.includes(id)){state.wins.push(id);persist();award(awards[Math.min(count,awards.length-1)]);if(state.wins.length===7)award('wolf');if(state.wins.length===12)award('star')}});
  window.addEventListener('nexus:signup',()=>setTimeout(()=>keeper('Welcome to the Nexus. Your choices will shape what happens here.'),300));
  window.nexusUseRetry=()=>{if(!(state.perks.retry>0))return false;state.perks.retry--;persist();return true};
  window.addEventListener('nexus:points',()=>{if(dlg.open&&active==='Hero')draw()});
  if(localStorage.getItem('hahnProfile'))visit();
  window.addEventListener('nexus:signup',visit);
})();
